import {useState, useCallback} from 'react'
import {useMutation} from 'react-relay'

import type {CreateProjectPageCreateProjectMutation} from '../__generated__/CreateProjectPageCreateProjectMutation.graphql'
import {mutation} from '../CreateProjectPage.queries'

type CreateProjectArg = {
  projectName: string
  projectId?: string
  description?: string
  parentProjectId?: string
}

export default function useCreateProject(): {
  createProject: (arg: CreateProjectArg) => Promise<string>
  projectCreating: boolean
  projectNameError: string | null
  projectIdError: string | null
  resetProjectCreateError: () => void
} {
  const [projectCreating, setProjectCreating] = useState<boolean>(false)
  const [projectNameError, setProjectNameError] = useState<string | null>(null)
  const [projectIdError, setProjectIdError] = useState<string | null>(null)
  const [commitMutation] = useMutation<CreateProjectPageCreateProjectMutation>(mutation)

  const createProject = useCallback(
    async ({projectName, projectId, description, parentProjectId}: CreateProjectArg) => {
      setProjectCreating(true)
      try {
        return await new Promise<string>((resolve, reject) => {
          commitMutation({
            variables: {
              input: {
                name: projectName,
                id: projectId || projectName.toLowerCase().replace(/\s+/g, '-'),
                description,
                parentProject: parentProjectId ? {id: parentProjectId} : undefined,
              },
            },
            onCompleted: () => {
              resolve('')
            },
            onError: error => {
              if (error.stack?.includes('DuplicateExternalIdException')) {
                setProjectIdError('A project with this ID already exists')
              } else if (error.stack?.includes('DuplicateProjectNameException')) {
                setProjectNameError('A project with this name already exists')
              } else if (error.stack?.includes('InvalidIdentifierException')) {
                setProjectIdError(
                  'Invalid project ID. IDs must start with a Latin letter, be no longer than 225 characters, and contain only Latin letters, numbers, and underscores.',
                )
              } else {
                setProjectIdError('An error occurred. Please try again later.')
              }
              reject(error)
            },
          })
        })
      } catch (e) {
        return 'An error occurred. Please try again later.'
      } finally {
        setProjectCreating(false)
      }
    },
    [commitMutation],
  )

  const resetProjectCreateError = useCallback(() => {
    setProjectIdError(null)
    setProjectNameError(null)
  }, [])

  return {projectCreating, createProject, projectNameError, projectIdError, resetProjectCreateError}
}
