import infoIcon from '@jetbrains/icons/info'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {capitalize} from 'lodash'
import type * as React from 'react'
import {useEffect, useState, useRef, useCallback} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {useQueryParam} from '../../../../hooks/routes'
import {getHrefWithQueryParams, getProjectHref} from '../../../../routes'
import {ROOT_PROJECT_ID, toProjectId} from '../../../../types'
import ParentProjectSelect from '../../../common/ParentProjectSelect/ParentProjectSelect'
import {useParentProjectSelect} from '../../../common/ParentProjectSelect/PipelineParentProjectSelect.hooks'
import {RouterButton} from '../../../common/RouterLink/RouterLink'
import CreateProjectInput from '../CreateProjectInput/CreateProjectInput'
import useCreateProject from '../hooks/useCreateProject'

import styles from './CreateProjectForm.module.css'

type CreateProjectFormProps = {
  className?: string
}

function CreateProjectForm({className}: CreateProjectFormProps) {
  const location = useLocation()
  const navigate = useNavigate()
  const cameFromUrl = useQueryParam('cameFromUrl')

  const {
    projectCreating,
    createProject,
    projectNameError,
    projectIdError,
    resetProjectCreateError,
  } = useCreateProject()
  const {selected} = useParentProjectSelect()
  const [projectName, setProjectName] = useState('')
  const [projectId, setProjectId] = useState('')
  const [description, setDescription] = useState('')
  const [projectNameUIError, setProjectNameUIError] = useState<string | null>(null)
  const [projectIdUIError, setProjectIdUIError] = useState<string | null>(null)

  const idManuallyChanged = useRef(false)
  const previousParentId = useRef<string | undefined>(undefined)

  /**
   * Generates a project ID based on the project name according to the rules:
   * 1. The first letter is capitalized
   * 2. Special characters except letters, numbers, and hyphens are removed
   * 3. Spaces are removed and the following letter is capitalized
   * 4. If a parent project is not Root, the parent project name is added with underscore
   */
  const generateProjectId = useCallback((name: string, parentProjectId?: string | null) => {
    if (!name) {
      return ''
    }

    // Start with the first letter capitalized
    let result = capitalize(name)

    // Remove special characters except letters, numbers, and hyphens
    result = result.replace(/[^a-zA-Z0-9\-\s]/g, '')

    // Handle spaces: remove them and capitalize the following letter
    result = result.replace(/\s+(.)/g, (_, char) => char.toUpperCase())

    // Remove any remaining spaces
    result = result.replace(/\s/g, '')

    if (
      parentProjectId &&
      parentProjectId !== ROOT_PROJECT_ID &&
      parentProjectId !== ROOT_PROJECT_ID
    ) {
      result = `${parentProjectId}_${result}`
    }

    return result
  }, [])

  const handleProjectNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newName = event.target.value
    setProjectName(newName)

    if (newName.length > 0) {
      resetProjectCreateError()
    }

    // Only update ID automatically if it hasn't been manually changed or is empty
    if (!idManuallyChanged.current || projectId === '') {
      setProjectId(generateProjectId(newName, selected?.id))
    }
  }

  const handleProjectIdChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newId = event.target.value
    setProjectId(newId)

    // Mark as manually changed if the user types something
    if (newId !== generateProjectId(projectName, selected?.id)) {
      idManuallyChanged.current = true
    }

    // If the field is cleared, reset the manual change flag
    if (newId === '') {
      idManuallyChanged.current = false
    }

    if (newId.length > 0) {
      if (!/^[a-zA-Z]/.test(newId)) {
        setProjectIdUIError('Wrong format: need to start from a letter character')
      } else {
        resetProjectCreateError()
      }
    }
  }

  const handleDescriptionChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setDescription(event.target.value)
  }

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault()
    let result = ''
    if (projectName && projectId) {
      result = await createProject({
        projectName,
        projectId,
        description,
        parentProjectId: selected?.id || undefined,
      })
    }
    if (result === '') {
      navigate(
        getHrefWithQueryParams(location, location.pathname, {
          setup: 'pipeline',
          projectId,
        }),
        {
          preventScrollReset: true,
        },
      )
    }
  }

  const [isFormValid, setFormValid] = useState(false)
  // Update project ID when the parent project changes
  useEffect(() => {
    // Check if the parent project has changed
    const parentChanged = previousParentId.current !== selected?.id
    previousParentId.current = selected?.id ?? undefined

    // Only update ID if parent changed or we have a name but no ID
    if (projectName && (parentChanged || projectId === '') && !idManuallyChanged.current) {
      setProjectId(generateProjectId(projectName, selected?.id))
    }
  }, [selected, projectName, projectId, generateProjectId])

  useEffect(() => {
    setFormValid(
      !!selected?.id &&
        !!projectName &&
        !!projectId &&
        projectNameError == null &&
        projectIdError == null &&
        projectNameUIError == null &&
        projectIdUIError == null,
    )
  }, [
    projectId,
    projectName,
    projectIdError,
    projectNameUIError,
    projectIdUIError,
    projectNameError,
    selected?.id,
  ])

  return (
    <form className={className} autoComplete="off" onSubmit={handleSubmit}>
      <div className={styles.formInner}>
        <div className={styles.parentProject}>
          <label>{'Parent project'}</label>
          <ParentProjectSelect includeRoot />
        </div>
        <div>
          <CreateProjectInput
            value={projectName}
            label={<Text size={Text.Size.M}>{'Project name'}</Text>}
            error={projectNameError || projectNameUIError}
            onChange={handleProjectNameChange}
            aria-label="Project name"
            onValidate={setProjectNameUIError}
            autofocus
          />
          {projectNameError && <Text className={styles.error}>{projectNameError}</Text>}
        </div>

        <div>
          <CreateProjectInput
            value={projectId}
            label={
              <>
                <Text size={Text.Size.M}>{'Project ID'}</Text>
                <Tooltip
                  title={
                    <div>
                      {
                        'This ID is used in URLs, REST API, HTTP requests to the server, and configuration settings in the TeamCity Data Directory. '
                      }
                    </div>
                  }
                >
                  <Link
                    href={'https://www.jetbrains.com/help/teamcity/cloud/2025.03/?Entity+IDs'}
                    target={'_blank'}
                    rel="noreferrer"
                    aria-label="Learn more about Project IDs"
                  >
                    <Icon glyph={infoIcon} className={styles.infoIcon} aria-hidden="true" />
                  </Link>
                </Tooltip>
              </>
            }
            error={projectIdError}
            onChange={handleProjectIdChange}
            aria-label="Project ID"
            onValidate={setProjectIdUIError}
          />
          {projectIdError && <Text className={styles.error}>{projectIdError}</Text>}
        </div>
        <CreateProjectInput
          value={description}
          label={
            <>
              <Text size={Text.Size.M}>{'Project description '}</Text>
              <Text size={Text.Size.M} info>
                {'(optional)'}
              </Text>
            </>
          }
          onChange={handleDescriptionChange}
          aria-label="Project description"
          error={null}
          multiline
        />
      </div>

      <ButtonSet className={styles.actions}>
        <Button
          type={'submit'}
          disabled={!isFormValid}
          loader={projectCreating}
          primary
          height={ControlsHeight.M}
        >
          {'Create'}
        </Button>
        {cameFromUrl ? (
          <Button href={cameFromUrl} height={ControlsHeight.M}>
            {'Cancel'}
          </Button>
        ) : (
          <RouterButton to={getProjectHref(toProjectId(''))} height={ControlsHeight.M}>
            {'Cancel'}
          </RouterButton>
        )}
      </ButtonSet>
    </form>
  )
}

export default CreateProjectForm
