import closeIcon from '@jetbrains/icons/close-20px.svg'
import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import classNames from 'classnames'
import type {EntryPointProps} from 'react-relay'

import {useQueryParam} from '../../../hooks/routes'
import {useDarkOrLightTheme} from '../../../hooks/theme/useDarkOrLightTheme'
import {usePermission} from '../../../hooks/usePermission'
import {getFavoriteProjectsHref, getProjectHref} from '../../../routes'
import {Permission, toProjectId} from '../../../types'
import Loader from '../../common/Loader/Loader'
import RouterLink from '../../common/RouterLink/RouterLink'
import RestScreenHeight from '../PipelinesPages/components/RestScreenHeight/RestScreenHeight'
import SetupProjectPage from '../ProjectPage/SetupProjectPage/SetupProjectPage'

import CreateProjectForm from './CreateProjectForm/CreateProjectForm'
import CreateProjectHeader from './CreateProjectHeader/CreateProjectHeader'
import useCreateProject from './hooks/useCreateProject'
import createProjectImageDark from './Project-dark.svg'
import createProjectImageLight from './Project-light.svg'

import styles from './CreateProjectPage.module.css'

function CreateProjectPage() {
  const {projectCreating} = useCreateProject()
  const cameFromUrl = useQueryParam('cameFromUrl')
  const theme = useDarkOrLightTheme()

  return (
    <div className={styles.page}>
      {projectCreating && (
        <div className={styles.loader}>
          <Loader />
        </div>
      )}
      <a href={cameFromUrl ?? getProjectHref(toProjectId(''))} aria-label="Close" role="button">
        <Icon className={styles.close} title={'Close'} glyph={closeIcon} aria-hidden="true" />
      </a>
      <div className={classNames(styles.container, {[styles.hidden]: projectCreating})}>
        <div className={styles.content}>
          <CreateProjectHeader />
          <div className={styles.projectForm}>
            <CreateProjectForm className={styles.projectForm} />
          </div>
        </div>
        <div className={styles.imageWrapper} aria-hidden="true">
          <img
            className={styles.image}
            alt="Create Project"
            src={theme === Theme.LIGHT ? createProjectImageLight : createProjectImageDark}
            width={460}
            height={460}
          />
        </div>
      </div>
    </div>
  )
}

function CreateProjectPageContainer(_: EntryPointProps<{}, {}, {}, {}>) {
  const setupParam = useQueryParam('setup')
  const projectIdString = useQueryParam('projectId')
  const projectId = projectIdString != null ? toProjectId(projectIdString) : null
  const canEditProject = usePermission(Permission.EDIT_PROJECT, projectId)

  return (
    <RestScreenHeight>
      {projectId && setupParam != null && setupParam !== '' ? (
        <SetupProjectPage projectId={projectId} />
      ) : (
        <>
          {canEditProject ? (
            <CreateProjectPage />
          ) : (
            <div className={styles.errorWrapper}>
              <ErrorMessage
                icon={lockIcon}
                message="Access denied"
                description="You do not have enough permissions to create new project"
                aria-live="polite"
              >
                <RouterLink to={getFavoriteProjectsHref()} aria-label="Go to the home page">
                  {'Go to the home page'}
                </RouterLink>
              </ErrorMessage>
            </div>
          )}
        </>
      )}
    </RestScreenHeight>
  )
}

export default CreateProjectPageContainer
export type CreateProjectPageComponent = typeof CreateProjectPageContainer
