import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import type {FocusEventHandler, RefObject} from 'react'
import {useEffect, useRef, useState} from 'react'

import styles from './CreateProjectInput.module.css'

type CommonProps = {
  value?: string
  label: React.ReactNode
  disabled?: boolean
  error: string | null
  placeholder?: string
  'aria-label'?: string
  onValidate?: (error: string | null) => void
  size?: Size
  autofocus?: boolean
  multiline?: boolean
}

type CreateProjectInputProps = CommonProps & {
  multiline?: false | undefined
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void
}

type CreateProjectInputAreaProps = CommonProps & {
  multiline: true
  onChange: (event: React.ChangeEvent<HTMLTextAreaElement>) => void
}

const focusWaitTimeOut = 300

function CreateProjectInput({
  value = '',
  label,
  disabled,
  error: initialError,
  placeholder,
  'aria-label': ariaLabel,
  onChange,
  size = Size.FULL,
  onValidate,
  autofocus = false,
  multiline,
}: CreateProjectInputProps | CreateProjectInputAreaProps) {
  const inputRef = useRef<HTMLInputElement | HTMLTextAreaElement>(null)
  const [error, setError] = useState<string | null>(initialError)

  useEffect(() => {
    if (autofocus) {
      setTimeout(() => {
        inputRef.current?.focus()
      }, focusWaitTimeOut)
    }
  }, [autofocus])

  const props = {
    label,
    disabled,
    error,
    value,
    size,
    placeholder,
    'aria-label': ariaLabel,
    autoComplete: 'off',
    onFocus: () => setError(null),
    autoFocus: autofocus,
    onBlur: (e => {
      const v = e.currentTarget.value.trim()
      if (v.length === 0) {
        onValidate?.("The field can't be empty")
      } else {
        onValidate?.(null)
      }
    }) as FocusEventHandler<HTMLInputElement | HTMLTextAreaElement>,
  }

  if (multiline === true) {
    return (
      <Input
        {...props}
        rows={5}
        multiline
        inputRef={inputRef as RefObject<HTMLTextAreaElement>}
        onChange={onChange}
        inputClassName={styles.multilineInput}
      />
    )
  }
  return (
    <Input
      {...props}
      inputRef={inputRef as RefObject<HTMLInputElement>}
      onChange={onChange}
      height={ControlsHeight.M}
    />
  )
}

export default CreateProjectInput
