import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useNavigate} from 'react-router'

import {useQueryParamState} from '../../../../hooks/routes'
import {useDarkOrLightTheme} from '../../../../hooks/theme/useDarkOrLightTheme'
import {usePermission} from '../../../../hooks/usePermission'
import {getFavoriteProjectsHref, getProjectHref} from '../../../../routes'
import {Permission, type ProjectId} from '../../../../types'
import RouterLink from '../../../common/RouterLink/RouterLink'
import CreatePipelineImageDark from '../../PipelinesPages/CreatePipelinePage/Pipeline-dark.svg'
import CreatePipelineImageLight from '../../PipelinesPages/CreatePipelinePage/Pipeline-light.svg'

import CreateBuildTypeImageDark from './Build-dark.svg'
import CreateBuildTypeImageLight from './Build-light.svg'
import SetupProjectForm from './SetupProjectForm/SetupProjectForm'
import SetupProjectHeader from './SetupProjectHeader/SetupProjectHeader'

import styles from './SetupProjectPage.module.css'

type Props = {
  projectId: ProjectId
}
function SetupProjectPage({projectId}: Props) {
  const [setup] = useQueryParamState('setup', null)
  const navigate = useNavigate()
  const theme = useDarkOrLightTheme()
  const CreatePipelineImage =
    theme === Theme.LIGHT ? CreatePipelineImageLight : CreatePipelineImageDark
  const CreateBuildTypeImage =
    theme === Theme.LIGHT ? CreateBuildTypeImageLight : CreateBuildTypeImageDark

  return (
    <div className={styles.page}>
      <IconButton
        className={styles.close}
        title={'Close'}
        icon={'close-20px'}
        onClick={() => navigate(getProjectHref(projectId ?? ''))}
      />
      <div className={styles.container}>
        <div className={styles.content}>
          <SetupProjectHeader />
          <div className={styles.projectForm}>
            <SetupProjectForm projectId={projectId} className={styles.projectForm} />
          </div>
        </div>
        <div className={styles.imageWrapper}>
          {setup === 'pipeline' && (
            <img
              className={styles.image}
              alt="Create Pipeline"
              src={CreatePipelineImage}
              width={460}
              height={460}
            />
          )}
          {setup === 'build' && (
            <img
              className={styles.image}
              alt="Create Build Configuration"
              src={CreateBuildTypeImage}
              width={460}
              height={481}
            />
          )}
        </div>
      </div>
    </div>
  )
}

function SetupProjectPageContainer({projectId}: Props) {
  const canEditProject = usePermission(Permission.EDIT_PROJECT, projectId)

  return (
    <>
      {canEditProject ? (
        <SetupProjectPage projectId={projectId} />
      ) : (
        <div className={styles.errorWrapper}>
          <ErrorMessage
            icon={lockIcon}
            message="Access denied"
            description="You do not have enough permissions to setup project"
          >
            <RouterLink to={getFavoriteProjectsHref()}>{'Go to the home page'}</RouterLink>
          </ErrorMessage>
        </div>
      )}
    </>
  )
}

export default SetupProjectPageContainer
