import {memo} from 'react'

import {useParentProjectSelect} from './PipelineParentProjectSelect.hooks'

import {ProjectBuildTypeSelect} from 'src/components/common/ProjectBuildTypeSelect/ProjectBuildTypeSelect'

type Props = {
  className?: string
  includeRoot?: boolean
}
function ParentProjectSelect({className, includeRoot = false}: Props) {
  const {selected, handleSelect} = useParentProjectSelect()

  return (
    <ProjectBuildTypeSelect
      className={className}
      selected={selected}
      includeRoot={includeRoot}
      buildTypesSelectable={false}
      projectsSelectable
      onSelect={handleSelect}
    />
  )
}

export default memo(ParentProjectSelect)
