import buildTypeIcon from '@jetbrains/icons/buildType-20px.svg'
import pipelineIcon from '@jetbrains/icons/pipeline-20px.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import {useEffect, useState} from 'react'

import {useQueryParamState} from '../../../../../hooks/routes'
import {getProjectHref} from '../../../../../routes'
import type {ProjectId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import Card from '../../../../common/Card/Card'
import Icon from '../../../../common/Icon/Icon'
import ParentProjectSelect from '../../../../common/ParentProjectSelect/ParentProjectSelect'
import {RouterButton} from '../../../../common/RouterLink/RouterLink'
import PipelineForm from '../../../PipelinesPages/components/PipelineForm/PipelineForm'
import {vcsAnyGitProvider} from '../../../PipelinesPages/CreatePipelinePage/CreatePipelinePage.consts'
import usePipelineVcsProviders from '../../../PipelinesPages/hooks/usePipelineVcsProviders'

import styles from './SetupProjectForm.module.css'

type SetupProjectFormProps = {
  projectId: ProjectId
  className?: string
}

function SetupProjectForm({projectId, className}: SetupProjectFormProps) {
  const [setup, setSetup] = useQueryParamState('setup', null)
  const [pipelinesActive, setPipelinesActive] = useState(setup === 'pipeline')
  const {vcsProviders, authorizedProvider, getVcsProvidersRefetch} =
    usePipelineVcsProviders(projectId)
  const handleCardClick = (pipelines: boolean) => {
    setPipelinesActive(pipelines)
  }

  useEffect(() => {
    setSetup(pipelinesActive ? 'pipeline' : 'build')
  }, [pipelinesActive, setSetup])

  return (
    <div className={className}>
      <div className={styles.formInner}>
        <div className={styles.parentProject}>
          <label>{'Parent project'}</label>
          <ParentProjectSelect includeRoot />
        </div>
        <div className={styles.inputs}>
          <div className={styles.toggleGroup}>
            <Card
              active={pipelinesActive}
              onClick={() => handleCardClick(true)}
              icon={pipelineIcon}
              content={
                <>
                  <Text bold>{'Pipeline'}</Text>
                  <Text info size={Text.Size.S}>
                    {
                      'Pipeline with multiple jobs, create and configure using visual editor or YAML.'
                    }
                  </Text>
                </>
              }
              tag={'Early access'}
            />
            <Card
              active={!pipelinesActive}
              onClick={() => handleCardClick(false)}
              icon={buildTypeIcon}
              content={
                <>
                  <Text bold>{'Build configuration'}</Text>
                  <Text info size={Text.Size.S}>
                    {'Single build, create and manage сhains from the administration or DSL.'}
                  </Text>
                </>
              }
            />
          </div>
          {pipelinesActive && (
            <>
              {vcsProviders == null ? (
                <Loader />
              ) : (
                <PipelineForm
                  key={projectId} // Reset form when projectId changes
                  projectId={projectId}
                  vcsProviders={vcsProviders}
                  authorizedProvider={authorizedProvider ?? vcsAnyGitProvider}
                  onVcsLogin={process.env.NODE_ENV !== 'test' ? getVcsProvidersRefetch : undefined}
                  cancelButton={
                    <RouterButton to={getProjectHref(projectId ?? '')} height={ControlsHeight.M}>
                      {'Skip'}
                    </RouterButton>
                  }
                />
              )}
            </>
          )}
          {!pipelinesActive && (
            <div>
              <div className={styles.buildConfigWarning}>
                <Icon className={styles.warningIcon} name="info-filled" />
                <Text size={Text.Size.S}>
                  {
                    "We're developing a unified UI for both pipelines and classic build configurations. For now, classic configurations are only supported in the traditional TeamCity UI."
                  }
                </Text>
                <Link
                  className={styles.link}
                  href={resolveRelative('/admin/createObjectMenu.html', {
                    projectId: stringifyId(projectId),
                    showMode: 'createBuildTypeMenu',
                    cameFromUrl: location.href,
                  })}
                >
                  {'Switch to regular UI'}
                </Link>
              </div>
              <ButtonSet className={styles.actions}>
                <Button
                  height={ControlsHeight.M}
                  type={'submit'}
                  primary
                  href={resolveRelative('/admin/createObjectMenu.html', {
                    projectId: stringifyId(projectId),
                    showMode: 'createBuildTypeMenu',
                    cameFromUrl: location.href,
                  })}
                >
                  {'Proceed'}
                </Button>
                <RouterButton to={getProjectHref(projectId ?? '')} height={ControlsHeight.M}>
                  {'Skip'}
                </RouterButton>
              </ButtonSet>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export default SetupProjectForm
