import {useQueryParamState} from '../../../hooks/routes'

import type {ProjectOrBuildTypeNode} from 'src/types'
import {toProjectId, getProjectFilter} from 'src/types'

export function useParentProjectSelect() {
  const [projectId, setProjectId] = useQueryParamState('projectId', null)

  const selected =
    projectId != null && projectId !== '' ? getProjectFilter(toProjectId(projectId)) : null
  const handleSelect = (newSelected?: ProjectOrBuildTypeNode | null) => {
    if (newSelected?.id) {
      setProjectId(newSelected.id)
    }
  }

  return {selected, handleSelect}
}
