import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import cn from 'classnames'
import type React from 'react'

import styles from './Card.module.css'

type Props = {
  active: boolean
  onClick: () => void
  icon?: string
  tag?: string
  content?: React.ReactNode
}

function Card(props: Props) {
  return (
    <button
      type="button"
      className={cn(
        styles.card,
        {[styles.cardInactive]: !props.active},
        {[styles.cardActive]: props.active},
      )}
      onClick={props.onClick}
      aria-pressed={props.active}
    >
      <div className={styles.iconAndTag}>
        <>{props.icon && <Icon glyph={props.icon} className={styles.cardIcon} />}</>
        {props.tag && (
          <Tag
            textColor={'var(--ring-success-color)'}
            backgroundColor={'var(--ring-added-background-color)'}
            readOnly
            render={tagProps => <span {...tagProps} />}
          >
            {props.tag}
          </Tag>
        )}
      </div>
      <div className={styles.cardContent}>{props.content}</div>
    </button>
  )
}

export default Card
